// screen resolution
#define R iResolution.xy

// minimum distance to objects
#define DIST_MIN 1.

// maximum distance to objects
#define DIST_MAX 50.0

// max number of steps for the ray-marching
#define RAY_MARCH_STEPS 100

// consider hit if we reach this distance
#define RAY_MARCH_PRECI 0.0001

// for ray direction computation
#define PI 3.14159265359

// Switch color default = 1
#define COLOR 1


// Colors
#if COLOR == 1
# define LEAF vec3(0.956862745, 0.309803922, 0.823529412)
# define GRASS vec3(0.0, 0.5, 0.0)
# define UNDERWATER vec3(0.0, 0.5, 1.)
# define TRUNC vec3(0.4, 0.2, 0.)
# define ROCK vec3(0.5, 0.55, 0.5)
# define DIRT vec3(0.313725, 0.156863, 0.0196078)
#elif COLOR == 2
# define LEAF vec3(0.0, 0.1, 0.0)
# define GRASS vec3(0.0, 0.1, 0.0)
# define UNDERWATER vec3(0.0, 0.1, 0.)
# define TRUNC vec3(0.2, 0.1, 0.)
# define ROCK vec3(0.05, 0.1, 0.05)
# define DIRT vec3(0., 0., 0.)
#elif COLOR == 3
# define LEAF vec3(1., 1., 1.)
# define GRASS vec3(0.9, 0.1, 0.1)
# define UNDERWATER vec3(0.7, 0.7, 1.)
# define TRUNC vec3(0.35, 0.25, 0.1)
# define ROCK vec3(0.7, 0.7, 0.7)
# define DIRT vec3(0.8, 0.8, 0.8)
#elif COLOR == 4
# define LEAF vec3(1., 0., 0.)
# define GRASS vec3(0., 0., 1.)
# define UNDERWATER vec3(0., 0., 1.)
# define TRUNC vec3(1., 1., 1.)
# define ROCK vec3(1., 1., 1.)
# define DIRT vec3(1., 1., 1.)
#endif


// ray structure
struct Ray
{
    vec3 o; // origin
    vec3 d; // direction
};

struct Surface
{
    float t; // surface distance
    vec3 c;  // surface color
};

//*============IMPORT FROM FILE ON CHAMILO=================//
float opUnion(float d1, float d2) { return min(d1, d2); }

float opSubtraction(float d1, float d2) { return max(-d1, d2); }

float opIntersection(float d1, float d2) { return max(d1, d2); }

float hash13(vec3 p)
{
    return fract(sin(dot(p, vec3(12.9898, 78.233, 45.5432))) * 43758.5453123);
}

float vnoise(in vec3 x)
{
    vec3 p = floor(x);
    vec3 f = fract(x);
    f = f * f * (3.0 - 2.0 * f);

    return mix(
        mix(mix(hash13(p + vec3(0., 0., 0.)), hash13(p + vec3(1., 0., 0.)), f.x),
            mix(hash13(p + vec3(0., 1., 0.)), hash13(p + vec3(1., 1., 0.)), f.x), f.y),
        mix(mix(hash13(p + vec3(0., 0., 1.)), hash13(p + vec3(1., 0., 1.)), f.x),
            mix(hash13(p + vec3(0., 1., 1.)), hash13(p + vec3(1., 1., 1.)), f.x), f.y),
        f.z);
}

float fnoise(in vec3 p, in float amplitude, in float frequency, in float persistence, in int nboctaves)
{
    float a = amplitude;
    float f = frequency;
    float n = 0.0;

    for (int i = 0; i < nboctaves; ++i)
    {
        n = n + a * vnoise(p * f);
        f = f * 2.;
        a = a * persistence;
    }

    return n;
}

//*=========================================================//

//*=========IMPORT FROM https://iquilezles.org/ ==============//
float sdBox(vec3 p, vec3 b)
{
    vec3 q = abs(p) - b;
    return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}

float sdRoundBox(vec3 p, vec3 b, float r)
{
    vec3 q = abs(p) - b;
    return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0) - r;
}

float dot2(in vec3 v) { return dot(v, v); }
float sdRoundCone(vec3 p, vec3 a, vec3 b, float r1, float r2)
{
    // sampling independent computations (only depend on shape)
    vec3 ba = b - a;
    float l2 = dot(ba, ba);
    float rr = r1 - r2;
    float a2 = l2 - rr * rr;
    float il2 = 1.0 / l2;

    // sampling dependant computations
    vec3 pa = p - a;
    float y = dot(pa, ba);
    float z = y - l2;
    float x2 = dot2(pa * l2 - ba * y);
    float y2 = y * y * l2;
    float z2 = z * z * l2;

    // Single square root!
    float k = sign(rr) * rr * rr * x2;
    if (sign(z) * a2 * z2 > k)
        return sqrt(x2 + z2) * il2 - r2;
    if (sign(y) * a2 * y2 < k)
        return sqrt(x2 + y2) * il2 - r1;
    return (sqrt(x2 * a2 * il2) + y * rr) * il2 - r1;
}

float sdSphere(vec3 p, float s)
{
    return length(p) - s;
}

float sdEllipsoidRightHalf(in vec3 p, in vec3 r)
{
    // Cut the ellipsoid in half along the x axis
    if (p.z > 0.0)
    {
        return 1.0;
    }
    float k0 = length(p / r);
    float k1 = length(p / (r * r));
    return k0 * (k0 - 1.0) / k1;
}

float sdEllipsoid(in vec3 p, in vec3 r)
{

    float k0 = length(p / r);
    float k1 = length(p / (r * r));
    return k0 * (k0 - 1.0) / k1;
}

//*==========================================================//

//*=======Smooth blending operators==========================//
//? FROM https://timcoster.com/2020/02/13/raymarching-shader-pt3-smooth-blending-operators/

float smoothIntersection(float distA, float distB, float k)
{
    float h = clamp(0.5 - 0.5 * (distA - distB) / k, 0., 1.);
    return mix(distA, distB, h) + k * h * (1. - h);
}

float smoothUnion(float distA, float distB, float k)
{
    float h = clamp(0.5 + 0.5 * (distA - distB) / k, 0., 1.);
    return mix(distA, distB, h) - k * h * (1. - h);
}

float smoothSubtraction(float distA, float distB, float k)
{
    float h = clamp(0.5 - 0.5 * (distB + distA) / k, 0., 1.);
    return mix(-distA, distB, h) + k * h * (1. - h);
}

//*==========================================================//

//*=======Textures===========================================//
vec3 grassTexture(in vec3 p)
{
    float n = fnoise(p * 1.5, 0.5, 2.0, 0.5, 3);

    // Adjust texture color
    vec3 texture = vec3(0.1, 0.5, 0.1) * n + vec3(0.1, 0.5, 0.1);
    return texture;
}

vec3 waterTexture(in vec3 p)
{
    float n = fnoise(p, 1.5, 1.0, 0.2, 3);

    // Adjust texture color
    vec3 texture = n * vec3(0.1, 0.7, 0.8);
    return texture;
}

vec3 leafTexture(in vec3 p)
{
    float n = fnoise(p * 70.0, 0.5, 2.0, 0.5, 3);

    // Adjust texture color
    vec3 texture = n * vec3(0.1, 0.7, 0.1);
    return texture;
}

vec3 dirtTexture(in vec3 p)
{
    float n = fnoise(p * 5.0, 0.5, 2.0, 0.5, 3);

    // Adjust texture color
    vec3 texture = n * vec3(0.5, 0.3, 0.1);
    return texture;
}

vec3 rockTexture(in vec3 p)
{
    float n = fnoise(p * 5.0, 0.5, 2.0, 0.5, 3);

    // Adjust texture color
    vec3 texture = n * vec3(0.5, 0.5, 0.5);
    return texture;
}
//*==========================================================//

//*=======Surfaces===========================================//
Surface sdTree(vec3 p)
{
    // Create tree leafs
    float leafs = smoothUnion(sdSphere(p, 0.5), sdSphere(p + vec3(0.5, 0., 0.), 0.5), 0.08);
    leafs = smoothUnion(leafs, sdSphere(p + vec3(0.25, -0.5, 0.), 0.5), 0.08);
    leafs = smoothUnion(leafs, sdSphere(p + vec3(0.25, 0, 0.25), 0.5), 0.08);
    leafs = smoothUnion(leafs, sdSphere(p + vec3(0.25, 0, -0.25), 0.5), 0.08);

    // Render leafs less flat
    leafs += sin(9. * p.x) * sin(9. * p.y) * sin(9. * p.z) * 0.02;

    Surface sLeafs = Surface(leafs, mix(LEAF, leafTexture(p), 0.3));

    // Trunc of the tree
    float trunc = sdRoundCone(p + vec3(0.25, 0., 0.), vec3(0., -0.8, 0.), vec3(0., 0.5, 0.), 0.2, 0.1);

    Surface sTrunc = Surface(trunc, TRUNC);

    if (leafs < trunc)
    {
        return sLeafs;
    }
    else
    {
        return sTrunc;
    }
}

Surface sdFloor(vec3 p)
{
    // Water cavity
    float waterCavity = sdEllipsoidRightHalf(p + vec3(-1., -0.35, -1.6), vec3(0.9, 0.5, 0.9));

    // Add some roughness to the water cavity
    waterCavity -= sin(20. * p.x) * sin(20. * p.y) * sin(20. * p.z) * 0.01;

    // Water in water cavity
    Surface sWater;
    float water = smoothIntersection(p.y - 0.2, waterCavity, 0.);
    // Avoid water to be rendered outside of the water cavity with a bounding box
    float limitMap = sdBox(p, vec3(1.5, 0.2, 1.5));
    water = smoothIntersection(water, limitMap, 0.01);

    // Add waves
    float amplitude = 0.01;
    vec3 waveDirection = vec3(p.x - 6., p.y, p.z - 4.);
    // Wave paterne
    float wave = amplitude * sin(dot2(waveDirection) + iTime * 2.);
    water += wave;

    sWater = Surface(water, mix(UNDERWATER, waterTexture(p), 0.5));

    // Floor
    float floor = opSubtraction(waterCavity, sdBox(p, vec3(1.5, 0.2, 1.5)));

    Surface sFloor = Surface(floor, mix(DIRT, dirtTexture(p), 0.5));

    // Grass
    float grass = opSubtraction(waterCavity, sdRoundBox(p + vec3(0., -0.2, 0.), vec3(1.50, 0., 1.50), 0.03));

    Surface sGrass = Surface(grass, mix(GRASS, grassTexture(p), 0.5));

    if (sFloor.t < sGrass.t)
    {
        return sFloor;
    }
    else if (sWater.t < sGrass.t)
    {
        return sWater;
    }
    else
    {
        return sGrass;
    }
}

Surface sdRocks(vec3 p)
{
    // Create rock
    float rock = sdEllipsoid(p - vec3(1.3, 0.06, -1.8), vec3(0.09, 0.09, 0.07));
    // Little rock add
    rock = min(rock, sdEllipsoid(p - vec3(1.26, 0.06, -1.68), vec3(0.04, 0.055, 0.04)));
    // Deform rock
    rock += sin(30. * p.x) * sin(30. * p.y + 5.5) * sin(28. * p.z) * 0.02;

    // Create rock2
    float rock2 = sdEllipsoid(p - vec3(1., 0.1, 0.), vec3(0.21, 0.2, 0.23));
    // Deform rock2
    rock2 += sin(10. * p.x) * sin(10. * p.y + 5.5) * sin(18. * p.z) * 0.02;

    Surface sRock = Surface(rock, mix(ROCK, rockTexture(p), 0.5));
    Surface sRock2 = Surface(rock2, mix(ROCK, rockTexture(p), 0.5));

    if (sRock2.t < sRock.t)
    {
        return sRock2;
    }
    else
    {
        return sRock;
    }
}

//*==========================================================//

// Scene function that returns the closest surface touched by the ray 
Surface scene(in vec3 p)
{
    // Initialize surfaces
    Surface floor = sdFloor(p);
    Surface tree = sdTree(p + vec3(0.5, -1, 0.5));
    Surface rock = sdRocks(p + vec3(1., -0.2, -1.));

    Surface currentSurface = floor;

    // Find the closest surface
    if (tree.t < currentSurface.t)
    {
        currentSurface = tree;
    }

    if (rock.t < currentSurface.t)
    {
        currentSurface = rock;
    }

    return currentSurface;
}

Surface march(in Ray r)
{
    float t = DIST_MIN;

    // For each step, we calculate the surface touched by the ray until we reach the maximum allowed distance
    for (int i = 0; i < RAY_MARCH_STEPS, t <= DIST_MAX; ++i)
    {
        Surface s = scene(r.o + t * r.d);

        // If we are close enough to the surface, we consider that we hit it
        if (s.t < RAY_MARCH_PRECI)
        {
            return Surface(t + s.t, s.c);
        }

        t = t + s.t;
    }

    // If we didn't hit any surface, we return the maximum distance with a black color
    return Surface(DIST_MAX, vec3(0., 0., 0.));
}

vec3 normalAt(in Surface s, in Ray r)
{
    const float e = 0.01;
    // ray origin + distance * rayon direction
    vec3 p = r.o + s.t * r.d;
    float nx = scene(vec3(p.x + e, p.y, p.z)).t - scene(vec3(p.x - e, p.y, p.z)).t;
    float ny = scene(vec3(p.x, p.y + e, p.z)).t - scene(vec3(p.x, p.y - e, p.z)).t;
    float nz = scene(vec3(p.x, p.y, p.z + e)).t - scene(vec3(p.x, p.y, p.z - e)).t;

    return normalize(vec3(nx, ny, nz));
}

vec3 shade(in Surface s, in Ray r)
{
    vec3 n = normalAt(s, r);

    // Light speed rotation
    float lightSpeedRotation = 0.1;
    // Light direction
    vec3 l = normalize(vec3(5. * cos(iTime * lightSpeedRotation), 25. / 3.0, 5. * sin(iTime * lightSpeedRotation)));
    vec3 v = normalize(-r.d);
    vec3 e = reflect(-l, n);

    // Diffuse Specular Ambient coefficients
    vec3 Kd = s.c;
    vec3 Ks = vec3(1.);
    vec3 Ka = vec3(0.17, 0.17, 0.17);

    float shininess = 50.;
    float diffuse = max(dot(n, l), 0.);
    float specular = pow(max(dot(e, v), 0.), shininess);

    // Add Ray to render shadow
    Ray shadowRay = Ray(r.o + s.t * r.d + 0.001 * n, l);
    Surface shadow = march(shadowRay);

    // If shadow ray hit, reduce the diffuse components
    if (shadow.t < DIST_MAX)
    {
        diffuse *= 0.5;
    }

    // Return the final color of the pixel
    return Kd * diffuse + Ks * specular + Ka;
}

Ray camRay(in vec2 p)
{
    // p is the current pixel coord, in [-1,1]

    // normalized mouse position
    vec2 m = iMouse.xy / R.y;

    // camera position
    float DP = 15.;
    float d = DP / 2.;
    // Speed of the rotation of the camera
    float speedRotate = 6.;
    vec3 ro = vec3(d * cos(6.0 * m.x), DP / 3.0, d * sin(6.0 * m.x));

    // rotate camera around the target point
    ro = vec3(d * cos(iTime * m.x * 0.3), DP / 3.0, d * sin(iTime * m.x * 0.3));

    // zoom screen adapting with iResolution
    ro = ro * (1. - 0.5 * m.y) * (R.x / R.y);
    // target point
    vec3 ta = vec3(0.0, 0.0, 0.0);

    // camera view vector
    vec3 cw = normalize(ta - ro);

    // camera up vector
    vec3 cp = vec3(0.0, 1.0, 0.0);

    // camera right vector
    vec3 cu = normalize(cross(cw, cp));

    // camera (normalized) up vector
    vec3 cv = normalize(cross(cu, cw));

    float fovDeg = 45.;
    float fovRad = (fovDeg / 360.) * 2. * PI;
    float zf = 1. / tan(fovRad / 2.);

    // view vector, including perspective (the more you multiply cw, the less fovy)
    vec3 rd = normalize(p.x * cu + p.y * cv * (R.y / R.x) + zf * cw);

    return Ray(ro, rd);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Gradient Background color
    vec3 c = vec3(0.3, 0.5, 0.6) + (0.8 - fragCoord.y / R.y);
    // Darken the background when zoom
    c = c * (1. - 0.5 * sin(iMouse.y / R.y ));

    vec2 uv = (fragCoord / R.xy) * 2. - 1.;

    // Generate the ray from the camera to uv coordinates
    Ray r = camRay(uv);

    // March the ray to find the closest surface
    Surface s = march(r);

    // If we hit a surface before the max distance, we shade it 
    if (s.t < DIST_MAX)
    {
        c = shade(s, r);
    }

    fragColor = vec4(c, 1.);
}
